def deliver(path, data):
    """Publish bytes with the installed synchronous writer."""
    return SwapWriter().publish(path, data)

personal/io/writer.py::SwapWriter.text:
class SwapWriter(CommitPort):
    """Sync: overwrite one file by atomic rename."""
    def publish(self, path, data):
        temporary = path.with_suffix('.pending')
        temporary.write_bytes(data)
        os.replace(temporary, path)

personal/lib/fence.py::Fence.text:
class Fence:
    """Policy only: status >= 500 AND attempts < limit; no execution."""
    def permits(self, status, attempts, limit):
        return status >= 500 and attempts < limit

personal/lib/ledger.py::Ledger.text:
class Ledger:
    """RAM-only: digest(payload) -> first ack; mutable, no disk."""
    def __init__(self):
        self.values = {}
    def remember(self, payload, ack):
        return self.values.setdefault(hashlib.sha256(payload).hexdigest(), ack)

